import{_ as t,o,c as a,a2 as c}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"Advanced billing semantics — 9-axis SSOT for kiwa @kiwa-test/payment v0.3","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/billing-semantics.md","filePath":"concepts/billing-semantics.md"}'),d={name:"concepts/billing-semantics.md"};function i(r,e,s,n,l,p){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="advanced-billing-semantics-—-9-axis-ssot-for-kiwa-kiwa-test-payment-v0-3" tabindex="-1">Advanced billing semantics — 9-axis SSOT for kiwa <code>@kiwa-test/payment</code> v0.3 <a class="header-anchor" href="#advanced-billing-semantics-—-9-axis-ssot-for-kiwa-kiwa-test-payment-v0-3" aria-label="Permalink to &quot;Advanced billing semantics — 9-axis SSOT for kiwa `@kiwa-test/payment` v0.3&quot;">​</a></h1><p>Introduced in v1.23-1, <code>@kiwa-test/payment</code> v0.3 raises the payment mock harness from a <strong>webhook signature + fixture builder</strong> surface to a full <strong>advanced billing semantics</strong> surface. Where v0.2 gave you <code>signWebhook</code> / <code>emit</code> / <code>verify</code> and 4 fixture events (checkout / subscription / paymentFailed / refund), v0.3 layers <strong>9 axes</strong> of provider-neutralised billing state on top.</p><p>The 9 axes are the observable envelope every real provider (Stripe, Paddle, Lemon Squeezy) converges on — mapped to the same neutral event names + state machines — so tests write once and re-run against any provider. This document is the SSOT for what each axis exists to test, what state machine it defines, and which real-provider behaviours it neutralises.</p><h2 id="why-9-axes-why-now" tabindex="-1">Why 9 axes, why now <a class="header-anchor" href="#why-9-axes-why-now" aria-label="Permalink to &quot;Why 9 axes, why now&quot;">​</a></h2><p>Payment testing has three failure modes that a webhook-only mock can&#39;t catch.</p><ul><li><strong>State-machine drift</strong>. A subscription&#39;s real lifecycle isn&#39;t <code>active</code> / <code>canceled</code> — it&#39;s a 5-state graph with transition guards (<code>active</code> → <code>upgraded</code> → <code>downgraded</code> → <code>paused</code> → <code>canceled</code>, with <code>reactivate</code> only allowed from <code>canceled</code>). Tests that only assert <code>event.type === &#39;customer.subscription.created&#39;</code> miss the guards, and production bugs surface as invalid transitions the merchant app permits but the provider rejects.</li><li><strong>Retry cadence</strong>. Real dunning is 4 attempts over ~1 week + a grace period. Tests that skip the retry loop miss uncollectible-flip regressions and let merchant apps ship without the grace-period UX.</li><li><strong>Cross-provider fidelity</strong>. Stripe defers proration to the next invoice; Paddle charges the difference immediately; Lemon Squeezy hosts checkout while Paddle inlines it. A neutral test surface makes these differences <strong>explicit assertions</strong>, not silent regressions.</li></ul><p>The 9 axes below are the smallest set that reproduces the full billing envelope across the 3 target providers. Each axis is an independent module under <code>@kiwa-test/payment/semantics/*</code>; each provides pure functions that operate on a <code>PaymentAdapter</code> (the same interface <code>createStripeMock</code> / <code>createPaddleMock</code> / <code>createLemonSqueezyMock</code> return) and emit a strongly typed <code>AxisStep</code> sequence.</p><h2 id="axis-1-—-dunning" tabindex="-1">Axis 1 — Dunning <a class="header-anchor" href="#axis-1-—-dunning" aria-label="Permalink to &quot;Axis 1 — Dunning&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce payment retry sequences for failed invoices. Real providers all run a scheduled retry cadence (Stripe Smart Retries default = 4 attempts over ~1 week, Paddle&#39;s dunning follows the merchant-configured schedule, Lemon Squeezy retries 4 times over 14 days).</p><p><strong>State machine</strong>. <code>active</code> → <code>in-grace-period</code> → <code>recovered</code> or <code>exhausted</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>startDunning({ invoiceId, amountCents, customerId, config })</code> — creates a session with default <code>maxAttempts: 4</code>, <code>retryIntervalMs: 3 days</code>, <code>gracePeriodMs: 1 day</code></li><li><code>dunningAttempt(adapter, session)</code> — runs the next attempt, emits <code>dunning.attempt</code>, transitions to <code>in-grace-period</code> after the last attempt</li><li><code>finalizeDunning(adapter, session, { succeed })</code> — transitions to terminal <code>recovered</code> (succeed=true) or <code>exhausted</code> (succeed=false), emits <code>invoice.paid</code> or <code>invoice.marked_uncollectible</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app doesn&#39;t render the &quot;we&#39;ll retry your card in 3 days&quot; grace-period UX. Test catches it by asserting <code>session.state === &#39;in-grace-period&#39;</code> between the last attempt and finalisation.</p><h2 id="axis-2-—-retry" tabindex="-1">Axis 2 — Retry <a class="header-anchor" href="#axis-2-—-retry" aria-label="Permalink to &quot;Axis 2 — Retry&quot;">​</a></h2><p><strong>Purpose</strong>. General-purpose exponential-backoff retry primitive independent of billing dunning. Used for webhook delivery retries, idempotent API retries, and 3DS challenge polling.</p><p><strong>State machine</strong>. <code>pending</code> → <code>retrying</code> → <code>delivered</code> or <code>dead-letter</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>startRetry({ jobId, config })</code> — default <code>maxAttempts: 5</code>, exponential backoff with jitter</li><li><code>retryDeliver(adapter, session)</code> — runs the next attempt, emits <code>webhook.retry_attempted</code></li><li><code>retryBackoffMs(attempt, config)</code> — pure computation of the next backoff window</li></ul><p><strong>Failure mode caught</strong>. Merchant app doesn&#39;t dead-letter after <code>maxAttempts</code>. Test catches it by asserting the terminal state matches the configured max.</p><h2 id="axis-3-—-3d-secure-v2" tabindex="-1">Axis 3 — 3D Secure v2 <a class="header-anchor" href="#axis-3-—-3d-secure-v2" aria-label="Permalink to &quot;Axis 3 — 3D Secure v2&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce EMVCo 3DS 2.2 challenge flow — fingerprint (device data collection), challenge (user interaction), result (accepted / rejected). Frictionless flow skips the challenge when issuer risk assessment is low.</p><p><strong>State machine</strong>. <code>fingerprint</code> → <code>challenge-pending</code> → <code>completed</code>, or <code>fingerprint</code> → <code>frictionless</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>startThreeDs({ paymentIntentId, amountCents, customerId })</code> — session starts in <code>fingerprint</code></li><li><code>threeDsRequestChallenge(adapter, session)</code> — emits <code>3ds.challenge_required</code>, transitions to <code>challenge-pending</code></li><li><code>threeDsSubmitChallenge(adapter, session, { transStatus })</code> — accepts <code>Y</code> / <code>N</code> / <code>A</code> / <code>C</code> / <code>U</code> / <code>R</code> per EMVCo spec, transitions to <code>completed</code></li><li><code>threeDsFrictionless(adapter, session)</code> — skips challenge, transitions directly to <code>frictionless</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app treats <code>frictionless</code> as <code>challenge-pending</code> and blocks checkout. Test catches it by asserting the terminal state distinguishes the two paths.</p><h2 id="axis-4-—-sca-strong-customer-authentication-psd2" tabindex="-1">Axis 4 — SCA (Strong Customer Authentication, PSD2) <a class="header-anchor" href="#axis-4-—-sca-strong-customer-authentication-psd2" aria-label="Permalink to &quot;Axis 4 — SCA (Strong Customer Authentication, PSD2)&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce PSD2 SCA evaluation — the EU regulation requiring 2-factor authentication above a threshold (~€30), with exemption categories (low-value, low-risk, trusted beneficiary, secure corporate payment, recurring, MIT) that let providers short-circuit the challenge.</p><p><strong>Key functions</strong>.</p><ul><li><code>startSca(...)</code> / <code>scaEvaluate(adapter, session)</code> / <code>scaAuthenticate(adapter, session, ...)</code> — see <code>packages/payment/src/semantics/sca.ts</code> for the exact signatures. <code>ScaExemption</code> values enumerate the 6 categories used by production Stripe / Paddle / Lemon Squeezy checkouts.</li></ul><p><strong>Failure mode caught</strong>. Merchant app doesn&#39;t apply the low-value exemption (&lt; €30) and forces 3DS on every micro-transaction. Test catches it by asserting <code>scaEvaluate</code> returns <code>exempt</code> with the expected exemption category.</p><h2 id="axis-5-—-psd2-mandate" tabindex="-1">Axis 5 — PSD2 mandate <a class="header-anchor" href="#axis-5-—-psd2-mandate" aria-label="Permalink to &quot;Axis 5 — PSD2 mandate&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce PSD2 payment mandate lifecycle — SEPA direct debit / Bacs / ACH mandate creation + consent grant + revocation. Merchants must record consent explicitly to legally debit recurring payments.</p><p><strong>State machine</strong>. <code>pending</code> → <code>active</code> → <code>revoked</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>createMandate({ customerId, scheme, iban })</code> — creates a mandate in <code>pending</code> state; scheme = <code>sepa-direct-debit</code> / <code>bacs</code> / <code>ach</code></li><li><code>grantConsent(mandate, { signedAt })</code> — transitions to <code>active</code>, records the consent timestamp</li><li><code>revokeMandate(mandate, { reason })</code> — transitions to <code>revoked</code>; the recorded consent stays queryable for audit</li></ul><p><strong>Failure mode caught</strong>. Merchant app debits a customer whose mandate is <code>revoked</code>. Test catches it by asserting the debit call throws when <code>mandate.state === &#39;revoked&#39;</code>.</p><h2 id="axis-6-—-subscription-lifecycle" tabindex="-1">Axis 6 — Subscription lifecycle <a class="header-anchor" href="#axis-6-—-subscription-lifecycle" aria-label="Permalink to &quot;Axis 6 — Subscription lifecycle&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce the 5-state subscription envelope every real provider converges on. Guards enforce valid transitions so tests fail loudly on invalid state moves.</p><p><strong>State machine</strong>. <code>active</code> → (<code>upgraded</code> | <code>downgraded</code> | <code>paused</code> | <code>canceled</code>); <code>paused</code> → <code>active</code> via <code>resumeSubscription</code>; <code>canceled</code> → <code>active</code> via <code>reactivateSubscription</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>createSubscription(adapter, { customerId, planId, amountCents, currency? })</code> — emits <code>subscription.created</code>, session starts in <code>active</code></li><li><code>changePlan(adapter, subscription, { newPlanId, newAmountCents })</code> — transitions to <code>upgraded</code> or <code>downgraded</code> based on the amount delta, records previous plan + amount in metadata</li><li><code>pauseSubscription</code> / <code>resumeSubscription</code> — pause and resume; equal-amount <code>changePlan</code> is rejected as a no-op</li><li><code>cancelSubscription</code> / <code>reactivateSubscription</code> — terminal cancel + reactivation from <code>canceled</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app allows <code>changePlan</code> from <code>paused</code> (must <code>resumeSubscription</code> first). Test catches it because the transition guard throws.</p><h2 id="axis-7-—-invoice-lifecycle" tabindex="-1">Axis 7 — Invoice lifecycle <a class="header-anchor" href="#axis-7-—-invoice-lifecycle" aria-label="Permalink to &quot;Axis 7 — Invoice lifecycle&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce the invoice state machine — draft, open, paid, void, uncollectible, with credit-note support.</p><p><strong>State machine</strong>. <code>draft</code> → <code>open</code> → (<code>paid</code> | <code>void</code> | <code>uncollectible</code>); any terminal state → <code>credited</code> (credit-note).</p><p><strong>Key functions</strong>.</p><ul><li><code>draftInvoice({ customerId, amountCents, currency })</code> — creates a <code>draft</code> invoice</li><li><code>openInvoice(adapter, invoice)</code> — emits <code>invoice.finalized</code>, transitions to <code>open</code></li><li><code>payInvoice(adapter, invoice)</code> — emits <code>invoice.paid</code>, transitions to <code>paid</code></li><li><code>voidInvoice</code> / <code>markUncollectible</code> / <code>creditNoteInvoice</code> — the remaining terminal transitions</li></ul><p><strong>Failure mode caught</strong>. Merchant app double-charges a paid invoice. Test catches it because <code>payInvoice</code> on a <code>paid</code> invoice throws.</p><h2 id="axis-8-—-tax-vat-gst-sales-tax" tabindex="-1">Axis 8 — Tax (VAT / GST / sales tax) <a class="header-anchor" href="#axis-8-—-tax-vat-gst-sales-tax" aria-label="Permalink to &quot;Axis 8 — Tax (VAT / GST / sales tax)&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce merchant-of-record tax auto-calculation. Merchant-of-record providers (Paddle, Lemon Squeezy) handle tax registration and remittance in ~180 jurisdictions; merchants book the neutralised <code>TaxLine</code> (net + tax + kind + reverseCharged + exempt flags).</p><p><strong>Key data types</strong>.</p><ul><li><code>TaxKind</code> = <code>vat</code> | <code>gst</code> | <code>sales-tax</code></li><li><code>TaxCalcInput</code> = <code>{ netAmountCents, buyerCountry, buyerVatId?, merchantCountry, productKind? }</code> where <code>productKind</code> is <code>digital</code> | <code>physical</code> | <code>service</code></li><li><code>TaxLine</code> = <code>{ kind, country, rateBps, amountCents, taxCents, reverseCharged, exempt }</code></li></ul><p><strong>Key functions</strong>.</p><ul><li><code>calculateTax(input)</code> — pure function; picks VAT (EU + UK), GST (JP / AU / NZ), sales tax (US / CA) from a deterministic rate table; applies reverse charge for B2B cross-border EU digital / service transactions with a <code>buyerVatId</code></li><li><code>emitTaxLine(adapter, { customerId, line })</code> — emits <code>tax.calculated</code> / <code>tax.reverse_charged</code> / <code>tax.exempted</code> as the neutral event</li></ul><p><strong>Failure mode caught</strong>. Merchant app double-taxes a B2B EU cross-border customer because it doesn&#39;t recognise reverse charge. Test catches it by asserting <code>line.reverseCharged === true</code> + <code>line.taxCents === 0</code> for a <code>DE</code> buyer with a <code>buyerVatId</code> when the merchant is in <code>FR</code>.</p><h2 id="axis-9-—-chargeback-dispute" tabindex="-1">Axis 9 — Chargeback dispute <a class="header-anchor" href="#axis-9-—-chargeback-dispute" aria-label="Permalink to &quot;Axis 9 — Chargeback dispute&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce the card-network dispute lifecycle — customer files, merchant submits evidence, network rules on the outcome, provider assesses fee.</p><p><strong>State machine</strong>. <code>opened</code> → <code>evidence-submitted</code> → <code>won</code> or <code>lost</code>.</p><p><strong>Key data types</strong>.</p><ul><li><code>ChargebackReason</code> = <code>fraudulent</code> | <code>unrecognized</code> | <code>duplicate</code> | <code>product-not-received</code> | <code>product-unacceptable</code> | <code>subscription-canceled</code> | <code>credit-not-processed</code> | <code>general</code></li><li><code>Chargeback</code> = <code>{ id, transactionId, customerId, amountCents, currency?, reason, state, history }</code></li></ul><p><strong>Key functions</strong>.</p><ul><li><code>openChargeback(adapter, { transactionId, customerId, amountCents, reason })</code> — customer files; session starts in <code>opened</code>, emits <code>chargeback.opened</code></li><li><code>submitEvidence(adapter, chargeback, { receiptUrl?, shippingProof?, customerCommunication? })</code> — transitions to <code>evidence-submitted</code>, emits <code>chargeback.evidence_submitted</code></li><li><code>resolveChargeback(adapter, chargeback, { merchantWon })</code> — network rules; <code>merchantWon: true</code> transitions to <code>won</code>, <code>false</code> to <code>lost</code>; the step metadata includes <code>disputeFeeCents</code> (0 on wins, ~$15 on lost)</li></ul><p><strong>Failure mode caught</strong>. Merchant app books the chargeback fee even on wins. Test catches it by asserting <code>step.metadata.disputeFeeCents === 0</code> on <code>won</code> outcomes.</p><h2 id="the-3-execution-modes-recap" tabindex="-1">The 3 execution modes recap <a class="header-anchor" href="#the-3-execution-modes-recap" aria-label="Permalink to &quot;The 3 execution modes recap&quot;">​</a></h2><p>Every axis works in the same 3 execution modes as the v1.22 real driver layer.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Trigger</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>mock only</code></td><td><code>KIWA_MODE</code> unset</td><td>Pure <code>@kiwa-test/payment</code> mock adapter, 0 network, sub-100 ms per test</td></tr><tr><td><code>real-optional</code></td><td><code>KIWA_MODE=real-optional</code></td><td>Try real driver; fall back to mock with a warning if credentials are missing</td></tr><tr><td><code>real-required</code></td><td><code>KIWA_MODE=real</code> + provider-specific keys</td><td>Fail hard if credentials are missing; run only against the live sandbox</td></tr></tbody></table><p>The 3 dogfood apps (<code>dogfood-stripe-billing-app</code>, <code>dogfood-paddle-merchant-app</code>, <code>dogfood-lemon-squeezy-app</code>) all wire this same mode switch — pass <code>KIWA_MODE=real</code> + <code>STRIPE_KEY</code> / <code>PADDLE_KEY</code> / <code>LEMONSQUEEZY_KEY</code> to swap the adapter without touching the axis test bodies.</p><h2 id="where-each-provider-surfaces" tabindex="-1">Where each provider surfaces <a class="header-anchor" href="#where-each-provider-surfaces" aria-label="Permalink to &quot;Where each provider surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Axis</th><th>Stripe surface</th><th>Paddle surface</th><th>Lemon Squeezy surface</th></tr></thead><tbody><tr><td>Dunning</td><td>Smart Retries (<code>invoice.marked_uncollectible</code>)</td><td>Dunning campaign (merchant-config)</td><td>Retry policy (4 × 14 days)</td></tr><tr><td>Retry</td><td><code>webhook.retry</code> header</td><td><code>paddle.retry</code> in signature</td><td><code>X-Retry-Attempt</code> header</td></tr><tr><td>3DS v2</td><td>PaymentIntent 3ds status</td><td>Inline SDK 3ds callback</td><td>Hosted checkout 3ds redirect</td></tr><tr><td>SCA</td><td>Automatic (<code>payment_intent.requires_action</code>)</td><td>Automatic (inline SDK)</td><td>Automatic (hosted checkout)</td></tr><tr><td>PSD2 mandate</td><td>SetupIntent + Mandate</td><td>Not exposed (MoR handles)</td><td>Not exposed (MoR handles)</td></tr><tr><td>Subscription</td><td>5-state <code>customer.subscription.*</code></td><td>Same envelope, immediate proration</td><td>Same envelope, MoR-owned invoices</td></tr><tr><td>Invoice</td><td><code>Invoice</code> object w/ state</td><td><code>Transaction</code> object w/ state</td><td><code>Order</code> + <code>Subscription</code> object</td></tr><tr><td>Tax</td><td>Stripe Tax (merchant registers)</td><td>Paddle MoR (auto-calc)</td><td>Lemon Squeezy MoR (auto-calc)</td></tr><tr><td>Chargeback</td><td><code>Dispute</code> object + $15 fee</td><td>Handled by Paddle (waived)</td><td>Handled by Lemon Squeezy (waived on wins)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/39-stripe-billing">Tutorial 39 — Stripe advanced billing</a></li><li><a href="./../tutorials/40-paddle-merchant">Tutorial 40 — Paddle merchant-of-record</a></li><li><a href="./../tutorials/41-lemon-squeezy-license">Tutorial 41 — Lemon Squeezy license flow</a></li><li><a href="./../migrations/v1.22-to-v1.23">Migration guide v1.22 → v1.23</a></li><li><a href="./payment-testing">Payment testing concept doc (v1.14 SSOT)</a></li></ul>',71)])])}const m=t(d,[["render",i]]);export{h as __pageData,m as default};
